globalThis.units = (...values) => values.map(function describe(v) {
  if (typeof v === "string") return ["s", v.length, Array.from({ length: v.length }, (_, i) => v.charCodeAt(i)).join(" ")]
  if (Array.isArray(v)) return ["a", v.map(describe)]
  if (v !== null && typeof v === "object") return ["o", Object.keys(v).map((k) => [describe(k), describe(v[k])])]
  return [typeof v, String(v)]
})

